import hmac
import hashlib

def sign_message(key, message):
    h = hmac.new(key.encode(), message.encode(), hashlib.sha256)
    return h.hexdigest()

def verify_signature(key, message, signature):
    good_sig = hmac.new(key.encode(), message.encode(), hashlib.sha256).digest()
    try:
        hmac.compare_digest(good_sig, bytes.fromhex(signature))
    except ValueError:
        return False
    return hmac.compare_digest(good_sig, bytes.fromhex(signature))
